// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(address target, uint256 value) public {
        vm.assume(target != address(0));
        vm.assume(value > 0);
        vm.deal(address(c), value);
        uint256 balanceBefore = address(c).balance;
        vm.prank(c.owner());
        c.sendMoney(target, value);
        uint256 balanceAfter = address(c).balance;
        assertTrue(balanceAfter == balanceBefore - value);
    }
}
